from pathlib import Path
import base64
import re

TEXT_FILES = {'apps/context42/parser.py': '', 'apps/context42/services.py': '', 'apps/context42/views.py': '', 'apps/context42/management/__init__.py': '', 'apps/context42/management/commands/__init__.py': '', 'apps/context42/management/commands/seed_context42.py': '', 'templates/context42/context42.html': '', 'templates/context42/upload_version.html': '', 'static/css/context42_v70_3.css': '', 'static/js/context42_v70_3.js': ''}

PARTIES_FILE = ''
LEGAL_FILE = ''


print("=== CONTEXTO 4.2 V70.3 - ESTILO 4.1 ===")


for filename, encoded in TEXT_FILES.items():
    path = Path(filename)
    path.parent.mkdir(
        parents=True,
        exist_ok=True,
    )

    if path.exists():
        backup = path.with_name(
            path.name
            + ".before_context42_v70_3.bak"
        )

        if not backup.exists():
            backup.write_text(
                path.read_text(
                    encoding="utf-8"
                ),
                encoding="utf-8",
            )

    path.write_bytes(
        base64.b64decode(
            encoded
        )
    )

    print(
        "OK:",
        filename,
    )


source_files = [
    (
        Path(
            "imports/"
            "07 - Partes Interesadas_V0.4.xlsx"
        ),
        PARTIES_FILE,
    ),
    (
        Path(
            "imports/"
            "03 - Lista_de_requisitos_legales_"
            "normativos_contractuales_V0.15.xlsm"
        ),
        LEGAL_FILE,
    ),
]

for path, encoded in source_files:
    path.parent.mkdir(
        parents=True,
        exist_ok=True,
    )

    if not path.exists():
        path.write_bytes(
            base64.b64decode(
                encoded
            )
        )

        print(
            "OK:",
            path,
        )
    else:
        print(
            "EXISTE:",
            path,
        )


# Ensure context42 is in INSTALLED_APPS.
settings_candidates = [
    Path("config/settings/base.py"),
    Path("config/settings.py"),
]

settings_path = next(
    (
        item
        for item in settings_candidates
        if item.exists()
    ),
    None,
)

if settings_path:
    text = settings_path.read_text(
        encoding="utf-8"
    )

    app_ref = (
        '"apps.context42.apps.Context42Config",'
    )

    if app_ref not in text:
        match = re.search(
            r"INSTALLED_APPS\s*=\s*\[\s*\n",
            text,
        )

        if match:
            pos = match.end()
            text = (
                text[:pos]
                + "    "
                + app_ref
                + "\n"
                + text[pos:]
            )

            settings_path.write_text(
                text,
                encoding="utf-8",
            )

            print(
                "OK: Context42Config registrado"
            )


# Ensure context42 URL include is present.
urls = Path(
    "config/urls.py"
)

if urls.exists():
    text = urls.read_text(
        encoding="utf-8"
    )

    if (
        'include("apps.context42.urls")'
        not in text
    ):
        match = re.search(
            r"urlpatterns\s*=\s*\[\s*\n",
            text,
        )

        if match:
            pos = match.end()

            text = (
                text[:pos]
                + '    path("", include("apps.context42.urls")),\n'
                + text[pos:]
            )

            urls.write_text(
                text,
                encoding="utf-8",
            )

            print(
                "OK: ruta context42 registrada"
            )


